const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [
      [-80.7, 42.5],
      [-79.0, 42.5],
      [-79.0, 40.8],
      [-80.7, 40.8]
    ],
    null,
    false
  ); // Northwestern Pennsylvania

  const date1_start = ee.Date('2020-02-22');
  const date1_end = date1_start.advance(1, 'day'); // A single day

  const date2_start = ee.Date('2020-03-01');
  const date2_end = date2_start.advance(1, 'day'); // A single day

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/051/MOD10A1');

  const getSnowCover = (dateStart, dateEnd, geometry) => {
    let col = collection.filterDate(dateStart, dateEnd)
      .filterBounds(geometry);

    const size = col.size().getInfo();
    if (size === 0) {
      return { collectionSize: 0, snowCover: null, pixels: 0, cloudCover: null };
    }

    // Use the first image in the collection for the day.
    // MOD10A1 is daily, so there should ideally be one image per day.
    let image = col.first();

    // Select the NDSI_Snow_Cover band
    let snow = image.select('NDSI_Snow_Cover');

    // MODIS MOD10A1 NDSI_Snow_Cover band values:
    // 0-100: Snow cover percentage
    // 200: Lake
    // 201: Ocean
    // 211: Inland water
    // 250: No snow
    // 254: Detector saturated
    // 255: Cloud
    // Mask out clouds (255), water (200, 201, 211), and saturated (254) pixels
    // We are interested in areas with actual snow (NDSI_Snow_Cover > 0 and <= 100)
    let snowMask = snow.updateMask(
      snow.gt(0).and(snow.lte(100))
    );

    // Calculate the percentage of valid snow pixels within the geometry
    const totalPixelsReducer = ee.Reducer.count();
    const snowPixelsReducer = ee.Reducer.sum().unweighted(); // Sums 1s from the snow mask

    const scale = 500; // MOD10A1 resolution

    // Get total pixels in the geometry (ignoring clouds, water etc. for now, just to get a base count for valid area)
    const totalValidPixelsResult = snow.mask(snow.neq(255).and(snow.neq(250)).and(snow.lt(200))).reduceRegion({
      reducer: totalPixelsReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    // Get number of snow-covered pixels (where NDSI_Snow_Cover > 0 and <= 100)
    const snowCountResult = snowMask.reduceRegion({
      reducer: snowPixelsReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    const totalValidPixels = totalValidPixelsResult.getInfo();
    const snowPixels = snowCountResult.getInfo();

    let snowCoverPercentage = 0;
    if (totalValidPixels > 0 && snowPixels !== null) {
      snowCoverPercentage = (snowPixels / totalValidPixels) * 100;
    } else if (totalValidPixels === 0) {
      // If no valid pixels in the region for the band after initial masking
      snowCoverPercentage = 0;
    }

    // Cloud cover is often important. Let's calculate the percentage of cloud pixels.
    const cloudMask = snow.eq(255);
    const cloudPixelsResult = cloudMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover'); // cloudMask is 0 or 1, sum gives count

    const allPixelsInRegion = geometry.area({'reducer': ee.Reducer.count(), 'scale': scale, 'maxPixels': 1e9}).divide(scale * scale).getInfo();
    const cloudPixels = cloudPixelsResult.getInfo();
    let cloudCoverPercentage = (cloudPixels / allPixelsInRegion) * 100;

    return {
      collectionSize: size,
      snowCover: snowCoverPercentage,
      pixels: totalValidPixels,
      cloudCover: cloudCoverPercentage
    };
  };

  const period1 = getSnowCover(date1_start, date1_end, geometry);
  const period2 = getSnowCover(date2_start, date2_end, geometry);

  console.log(`2020-02-22 Images: ${period1.collectionSize}`);
  if (period1.collectionSize === 0) {
    console.log("No images found for 2020-02-22.");
    console.log("C1");
    return;
  }
  console.log(`2020-02-22 Valid Pixels: ${period1.pixels}, Snow Cover: ${period1.snowCover !== null ? period1.snowCover.toFixed(2) : 'N/A'}%, Cloud Cover: ${period1.cloudCover !== null ? period1.cloudCover.toFixed(2) : 'N/A'}%`);

  console.log(`2020-03-01 Images: ${period2.collectionSize}`);
  if (period2.collectionSize === 0) {
    console.log("No images found for 2020-03-01.");
    console.log("C1");
    return;
  }
  console.log(`2020-03-01 Valid Pixels: ${period2.pixels}, Snow Cover: ${period2.snowCover !== null ? period2.snowCover.toFixed(2) : 'N/A'}%, Cloud Cover: ${period2.cloudCover !== null ? period2.cloudCover.toFixed(2) : 'N/A'}%`);

  // 3. Check for C2: No Valid Pixels after masking
  if (period1.pixels === 0 || period2.pixels === 0 || period1.snowCover === null || period2.snowCover === null) {
    console.log("No valid pixels after masking or snow cover calculation failed for one or both periods.");
    console.log("C2");
    return;
  }

  // 4. Calculation & 5. Validation
  if (period1.snowCover === null || period2.snowCover === null) {
    console.log("Snow cover calculation resulted in null values.");
    console.log("C3");
    return;
  }

  if (period2.snowCover > period1.snowCover) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
